import {
  AfterViewInit,
  ChangeDetectorRef,
  computed,
  Directive,
  effect,
  ElementRef,
  inject,
  input,
  OnDestroy,
  Renderer2,
  Signal,
} from '@angular/core';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { QPopoverComponent } from './popover.component';

interface HTMLElementWithPopover extends HTMLElement {
  showPopover: (options?: { source?: HTMLElement }) => void;
  hidePopover: () => void;
}

@Directive({
  selector: '[qPopoverTriggerFor]',
  exportAs: 'qPopoverTrigger',
  host: {
    'class': 'q-popover-trigger',
    '[attr.data-qt]': 'dataQt()',
    '[attr.role]': '"button"',
    '(click)': '_handleClick()',
    '(keydown)': '_handleKeydown($event)',
  },
})
export class QPopoverTriggerDirective implements AfterViewInit, OnDestroy {
  popover = input.required<QPopoverComponent>({ alias: 'qPopoverTriggerFor' });
  dataQt = input('q-popover-trigger', { alias: 'qPopoverTriggerDataQt' });

  private _popoverOpen = false;
  private _popoverHost: Signal<HTMLElementWithPopover | null> = computed(() =>
    this.popover()._getHostElement?.(),
  );
  private _cleanupHoverListeners: (() => void) | null = null;
  private readonly _renderer = inject(Renderer2);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _triggerElement = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;

  constructor() {
    effect(() => {
      this._initializePopoverConnection();
    });
  }

  ngAfterViewInit(): void {
    this._initializePopoverConnection();
  }

  ngOnDestroy(): void {
    this._cleanupPopoverConnection();
    this._cleanupHoverListeners?.();
  }

  togglePopover(): void {
    return this._popoverOpen ? this.closePopover() : this.openPopover();
  }

  openPopover(): void {
    if (this._popoverOpen) return;

    (this._popoverHost() as HTMLElementWithPopover).showPopover({
      source: this._triggerElement,
    });
  }

  closePopover(): void {
    this._popoverHost()?.hidePopover();
  }

  _handleKeydown(event: KeyboardEvent): void {
    const code = event.code;

    if (code === ENTER || code === SPACE) {
      event.preventDefault();
      event.stopPropagation();

      this.togglePopover();
    }
  }

  _handleClick(): void {
    this.togglePopover();
  }

  private _initializePopoverConnection(): void {
    this._cleanupPopoverConnection();
    this._setupPopoverConnection();
    this._setupTriggerHoverListeners();
  }

  private _setupPopoverConnection(): void {
    this.popover()._disableAutoTriggerSetupMethod?.();
    this.popover()._popoverDirective?.setPopoverTriggerElement(this._triggerElement);
    this._popoverHost()?.addEventListener('toggle', this._handlePopoverToggle);
  }

  private _cleanupPopoverConnection(): void {
    this._popoverHost()?.removeEventListener('toggle', this._handlePopoverToggle);
  }

  private _handlePopoverToggle = (event: Event): void => {
    const toggleEvent = event as ToggleEvent;
    this._popoverOpen = toggleEvent.newState === 'open';
    this._cdr.markForCheck();
  };

  private _setupTriggerHoverListeners(): void {
    this._cleanupHoverListeners?.();
    this._cleanupHoverListeners = null;

    if (!this._isHintPopover()) {
      return;
    }

    const cleanupFunctions = [...this._setupTriggerListeners(), ...this._setupPopoverListeners()];

    this._cleanupHoverListeners = (): void => {
      cleanupFunctions.forEach((cleanup) => cleanup());
    };
  }

  private _isHintPopover(): boolean {
    return this.popover()._getHostElement?.().getAttribute('popover') === 'hint';
  }

  private _setupTriggerListeners(): (() => void)[] {
    const triggerEl = this._triggerElement;

    return [
      this._renderer.listen(triggerEl, 'mouseenter', this._handleMouseEnter),
      this._renderer.listen(triggerEl, 'mouseleave', this._handleMouseLeave),
      this._renderer.listen(triggerEl, 'focus', this._handleMouseEnter),
      this._renderer.listen(triggerEl, 'blur', this._handleMouseLeave),
    ];
  }

  private _setupPopoverListeners(): (() => void)[] {
    const popoverEl = this.popover()?._getHostElement?.();

    return [
      this._renderer.listen(popoverEl, 'mouseenter', this._handleMouseEnter),
      this._renderer.listen(popoverEl, 'mouseleave', this._handleMouseLeave),
    ];
  }

  private _handleMouseEnter = (): void => {
    this.popover()._triggerMouseEnter?.();
  };

  private _handleMouseLeave = (): void => {
    this.popover()._triggerMouseLeave?.();
  };
}
